package com.nullchannel.android;

import android.app.Activity;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import org.json.JSONObject;

/** Private native UI. Notification entry requires a single-use encrypted launch proof. */
public final class NativeIncomingCallActivity extends Activity {
    private static java.lang.ref.WeakReference<NativeIncomingCallActivity> visible=new java.lang.ref.WeakReference<>(null);
    private String id="";
    private LinearLayout content;
    private final Handler handler=new Handler(Looper.getMainLooper());
    private final Runnable tick=new Runnable(){public void run(){render();handler.postDelayed(this,1000);}};
    static void changed(){NativeIncomingCallActivity activity=visible.get();if(activity!=null)activity.runOnUiThread(activity::render);}
    static boolean validPending(Context context,String id){try{String raw=NativeVault.get(context,"invitation."+id);return raw!=null&&new JSONObject(raw).optLong("expiresAt")>System.currentTimeMillis();}catch(Exception invalid){return false;}}
    static void persist(Context context,JSONObject invitation){try{NativeVault.put(context,"invitation."+invitation.getString("callId"),invitation.toString());}catch(Exception ignored){}}
    static void open(Context context,String id){try{String raw=NativeVault.get(context,"invitation."+id);JSONObject view=NativeCallSignaling.snapshot();String room=raw!=null?new JSONObject(raw).getString("roomCode"):view.optString("roomCode");NativeNotifications.launch(context,room,id,"open").send();}catch(Exception unavailable){}}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);if(Build.VERSION.SDK_INT>=27){setShowWhenLocked(true);setTurnScreenOn(true);}else getWindow().addFlags(WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);visible=new java.lang.ref.WeakReference<>(this);if(saved!=null){id=saved.getString("callId","");if(!NativeCallSignaling.owns(id)){if(!validPending(this,id)){finish();return;}try{NativeCallSignaling.begin(this,new JSONObject(NativeVault.get(this,"invitation."+id))).whenComplete((value,error)->runOnUiThread(()->{if(error!=null)finish();else render();}));}catch(Exception invalid){finish();return;}}}else if(!consume(getIntent())){finish();return;}content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setGravity(Gravity.CENTER);content.setPadding(32,32,32,48);content.setBackgroundColor(Color.rgb(8,16,22));android.widget.ScrollView scrolling=new android.widget.ScrollView(this);scrolling.setFillViewport(true);scrolling.addView(content);setContentView(scrolling);scrolling.setOnApplyWindowInsetsListener((view,insets)->{content.setPadding(32+insets.getSystemWindowInsetLeft(),32+insets.getSystemWindowInsetTop(),32+insets.getSystemWindowInsetRight(),48+insets.getSystemWindowInsetBottom());return insets;});handler.post(tick);}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);if(consume(intent))render();}
    private boolean consume(Intent intent){JSONObject proof=NativeVault.consumeAction(this,intent.getStringExtra("notificationNonce"));if(proof==null)return false;String next=proof.optString("callId");if(!next.matches("[a-f0-9-]{36}")||!NativeCallSignaling.owns(next)&&!validPending(this,next))return false;if(!id.isEmpty()&&!id.equals(next))return false;id=next;if(!NativeCallSignaling.owns(id)){try{String raw=NativeVault.get(this,"invitation."+id);if(raw==null)return false;JSONObject options=new JSONObject(raw);NativeCallSignaling.begin(this,options).whenComplete((value,error)->runOnUiThread(()->{if(error!=null)finish();else if(proof.optString("action").equals("answer"))answer();else render();}));}catch(Exception invalid){return false;}}else if(proof.optString("action").equals("answer"))handler.post(this::answer);return true;}
    private void answer(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},42);return;}NativeCallSignaling.command("answer",id);}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==42){if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)NativeCallSignaling.command("answer",id);else{NativeCallSignaling.command("decline",id);render();}}if(request==43)outputs();}
    private TextView text(String label,int size){TextView view=new TextView(this);view.setText(label);view.setTextSize(size);view.setTextColor(Color.WHITE);view.setGravity(Gravity.CENTER);content.addView(view,new LinearLayout.LayoutParams(-1,-2));return view;}
    private void button(String label,Runnable action){Button button=new Button(this);button.setText(label);button.setContentDescription(label);button.setMinHeight(64);button.setOnClickListener(view->action.run());LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,-2);params.setMargins(8,12,8,4);content.addView(button,params);}
    private void render(){if(content==null)return;JSONObject view=NativeCallSignaling.snapshot();if(!id.equals(view.optString("callId"))&&!id.equals(view.optString("ownershipId")))return;content.removeAllViews();text("NULLCHANNEL",18);text("Private voice call",30);String phase=view.optString("phase","incoming");boolean locked=getSystemService(android.app.KeyguardManager.class).isKeyguardLocked();text(locked?"Anonymous caller":view.optString("peerName","Anonymous caller"),22);long connected=view.optLong("connectedAt");text(phase.equals("connected")&&connected>0?String.format(java.util.Locale.ROOT,"%02d:%02d",(System.currentTimeMillis()-connected)/60000,(System.currentTimeMillis()-connected)/1000%60):phase,18);String message=view.optString("message");if(!message.isEmpty())text(message,16);
        if(phase.equals("incoming")){if(!view.optBoolean("accepting"))button("Answer",this::answer);else text("Connecting…",18);button("Decline",()->NativeCallSignaling.command("decline",id));}
        else if(!phase.equals("ended")&&!phase.equals("failed")){button(view.optBoolean("muted")?"Unmute":"Mute",()->NativeCallSignaling.command("mute",id));button("Audio output",()->{if(Build.VERSION.SDK_INT>=31&&checkSelfPermission(android.Manifest.permission.BLUETOOTH_CONNECT)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.BLUETOOTH_CONNECT},43);else outputs();});button("End call",()->NativeCallSignaling.command("end",id));}
        else button("Close",this::finish);
    }
    private void outputs(){NativePeer.routes(null).whenComplete((state,error)->runOnUiThread(()->{if(error!=null||isFinishing())return;org.json.JSONArray routes=state.optJSONArray("routes");if(routes==null)return;String[] labels=new String[routes.length()];for(int i=0;i<labels.length;i++)labels[i]=routes.optJSONObject(i).optString("label","Audio output");new android.app.AlertDialog.Builder(this).setTitle("Audio output").setItems(labels,(dialog,index)->NativePeer.routes(routes.optJSONObject(index).optString("id"))).show();}));}
    @Override protected void onSaveInstanceState(Bundle state){state.putString("callId",id);super.onSaveInstanceState(state);}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(visible.get()==this)visible.clear();super.onDestroy();}
}
